CREATE TABLE public.profile_history (id uuid PRIMARY KEY, full_name text NOT NULL);
GRANT SELECT ON public.profile_history TO authenticated;
GRANT ALL ON public.profile_history TO service_role;
ALTER TABLE public.profile_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_history_staff_read ON public.profile_history FOR SELECT TO authenticated USING (public.is_staff());
INSERT INTO public.profile_history(id,full_name) SELECT id,full_name FROM public.profiles;
CREATE FUNCTION public.sync_profile_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profile_history(id,full_name) VALUES(NEW.id,NEW.full_name) ON CONFLICT(id) DO UPDATE SET full_name=EXCLUDED.full_name; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.sync_profile_history() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER profile_history_sync BEFORE INSERT OR UPDATE OF full_name ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.sync_profile_history();
DO $$ DECLARE c record; BEGIN FOR c IN SELECT conname,conrelid::regclass AS tbl,att.attname AS col FROM pg_constraint pc JOIN pg_attribute att ON att.attrelid=pc.conrelid AND att.attnum=pc.conkey[1] WHERE pc.contype='f' AND pc.confrelid='public.profiles'::regclass AND NOT(pc.conrelid='public.seller_requests'::regclass AND att.attname='user_id') LOOP EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I',c.tbl,c.conname); EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY (%I) REFERENCES public.profile_history(id) DEFERRABLE INITIALLY DEFERRED',c.tbl,c.conname,c.col); END LOOP; END $$;
DO $$ DECLARE v text; BEGIN SELECT pg_get_viewdef('public.customer_list'::regclass,true) INTO v; EXECUTE 'CREATE OR REPLACE VIEW public.customer_list WITH (security_invoker=true) AS '||replace(v,'LEFT JOIN profiles ex','LEFT JOIN profile_history ex'); SELECT pg_get_viewdef('public.order_list'::regclass,true) INTO v; EXECUTE 'CREATE OR REPLACE VIEW public.order_list WITH (security_invoker=true) AS '||replace(v,'LEFT JOIN profiles ex','LEFT JOIN profile_history ex'); END $$;
CREATE OR REPLACE FUNCTION public.portal_executive_json(p_exec uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('id',h.id,'full_name',h.full_name,'job_title',p.job_title,'email',p.email,'phone',p.phone,'whatsapp',p.whatsapp,'photo_url',p.photo_url) FROM public.profile_history h LEFT JOIN public.profiles p ON p.id=h.id WHERE h.id=p_exec $$;
DO $$ DECLARE v text; BEGIN SELECT pg_get_functiondef('public.tg_customer_normalise()'::regprocedure) INTO v; EXECUTE replace(v,'if not exists (select 1 from public.profiles p','if (tg_op = ''INSERT'' or new.assigned_executive_id is distinct from old.assigned_executive_id) and not exists (select 1 from public.profiles p'); SELECT pg_get_functiondef('public.tg_order_before()'::regprocedure) INTO v; EXECUTE replace(v,'if new.executive_override_id is not null and not exists (','if (tg_op = ''INSERT'' or new.executive_override_id is distinct from old.executive_override_id) and new.executive_override_id is not null and not exists ('); END $$;
CREATE TABLE public.seller_signup_limits (bucket text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 0);
GRANT ALL ON public.seller_signup_limits TO service_role;
ALTER TABLE public.seller_signup_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_seller_signup(p_bucket text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.seller_signup_limits(bucket,attempts) VALUES(md5(p_bucket),1) ON CONFLICT(bucket) DO UPDATE SET window_start=CASE WHEN seller_signup_limits.window_start<now()-interval '1 hour' THEN now() ELSE seller_signup_limits.window_start END, attempts=CASE WHEN seller_signup_limits.window_start<now()-interval '1 hour' THEN 1 ELSE seller_signup_limits.attempts+1 END RETURNING attempts INTO n; RETURN n<=10; END $$;
REVOKE ALL ON FUNCTION public.consume_seller_signup(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_seller_signup(text) TO service_role;
COMMENT ON TABLE public.profile_history IS 'Name-only historical identities survive account/profile deletion; never an authentication or active staff directory.';